pub fn tr_fails_changed(words: &winnow_grammar::InternerContext, ruled: &collections::BTreeMap<String, TrRuled>, items: &[Spanned<Item>]) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    for item in items.iter() {
        match &item.node {
            Item::Impl { target, methods, .. } => {
                let owner = words.resolve(target.name).to_owned();
                if !ruled.contains_key(&owner) { continue; }
                let mut fails = false;
                for m in methods.iter() {
                    match &m.node {
                        Item::Fn { receiver, can_throw, .. } => {
                            let can_throw = *can_throw;
                            let how = match receiver { Some(__nikaia_value) => __nikaia_value, None => continue };
                            if how.is_mut && can_throw { fails = true; }
                        },
                        _ => { },
                    }
                }
                if fails { out.insert(owner); }
            },
            _ => { },
        }
    }
    out
}

pub(crate) fn tr_item_blocks(item: &Item) -> Vec<&Block> {
    let mut out: Vec<&Block> = vec![];
    match item {
        Item::Fn { body, .. } => { out.push(body); },
        Item::Test { body, .. } => { out.push(body); },
        Item::Bench { body, .. } => { out.push(body); },
        Item::Impl { methods, .. } => { for method in methods.iter() { out.extend(tr_item_blocks(&method.node)); } },
        _ => { },
    }
    out
}

pub(crate) fn tr_in_block(block: &Block, targets: bool) -> Vec<&Expr> {
    let mut out: Vec<&Expr> = vec![];
    for stmt in block.stmts.iter() { out.extend(tr_in_stmt(&stmt.node, targets)); }
    out
}

pub(crate) fn tr_in_stmt(stmt: &Stmt, targets: bool) -> Vec<&Expr> {
    let mut out: Vec<&Expr> = vec![];
    match stmt {
        Stmt::Let { value, .. } => { out.extend(tr_in_expr(value, targets)); },
        Stmt::Assign { target, value, .. } => {
            if targets { out.push(target); }
            out.extend(tr_in_expr(target, targets));
            out.extend(tr_in_expr(value, targets));
        },
        Stmt::For { iter, body, .. } => {
            out.extend(tr_in_expr(iter, targets));
            out.extend(tr_in_block(body, targets));
        },
        Stmt::While { cond, body } => {
            out.extend(tr_in_expr(cond, targets));
            out.extend(tr_in_block(body, targets));
        },
        Stmt::Return(value) => { out.extend(tr_in_maybe((value).as_ref(), targets)); },
        Stmt::Expr(value) => { out.extend(tr_in_expr(value, targets)); },
        _ => { },
    }
    out
}

pub(crate) fn tr_in_maybe(expr: Option<&Expr>, targets: bool) -> Vec<&Expr> { tr_in_expr(match expr { Some(__nikaia_value) => __nikaia_value, None => return vec![] }, targets) }

pub(crate) fn tr_in_all(all: &[Expr], targets: bool) -> Vec<&Expr> {
    let mut out: Vec<&Expr> = vec![];
    for each in all.iter() { out.extend(tr_in_expr(each, targets)); }
    out
}

pub(crate) fn tr_in_config(config: &[ConfigArg], targets: bool) -> Vec<&Expr> {
    let mut out: Vec<&Expr> = vec![];
    for option in config.iter() { out.extend(tr_in_expr(&option.value, targets)); }
    out
}

pub(crate) fn tr_in_expr(expr: &Expr, targets: bool) -> Vec<&Expr> {
    let mut out: Vec<&Expr> = vec![];
    if !targets { out.push(expr); }
    match expr {
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            out.extend(tr_in_expr(func, targets));
            out.extend(tr_in_all(args, targets));
            out.extend(tr_in_config(config, targets));
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            out.extend(tr_in_expr(receiver, targets));
            out.extend(tr_in_all(args, targets));
            out.extend(tr_in_config(config, targets));
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            out.extend(tr_in_expr(receiver, targets));
            out.extend(tr_in_all(args, targets));
            out.extend(tr_in_config(config, targets));
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            out.extend(tr_in_expr(lhs, targets));
            out.extend(tr_in_expr(rhs, targets));
        },
        Expr::Unary { expr: inner, .. } => { let inner = nikaia_std::boxed::open(inner); out.extend(tr_in_expr(inner, targets)); },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); out.extend(tr_in_expr(inner, targets)); },
        Expr::Throw(inner, _) => { let inner = nikaia_std::boxed::open(inner); out.extend(tr_in_expr(inner, targets)); },
        Expr::Cast { expr: inner, .. } => { let inner = nikaia_std::boxed::open(inner); out.extend(tr_in_expr(inner, targets)); },
        Expr::Return(value, _) => { let value = nikaia_std::boxed::open(value); out.extend(tr_in_maybe((value).as_ref(), targets)); },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); out.extend(tr_in_expr(base, targets)); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); out.extend(tr_in_expr(base, targets)); },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            out.extend(tr_in_expr(base, targets));
            out.extend(tr_in_expr(index, targets));
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            out.extend(tr_in_expr(start, targets));
            out.extend(tr_in_expr(end, targets));
        },
        Expr::Tuple(items, _) => { out.extend(tr_in_all(items, targets)); },
        Expr::ListLit { items, .. } => { out.extend(tr_in_all(items, targets)); },
        Expr::ListRepeat { value, count, .. } => {
            let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count);
            out.extend(tr_in_expr(value, targets));
            out.extend(tr_in_expr(count, targets));
        },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            out.extend(tr_in_expr(value, targets));
            out.extend(tr_in_expr(fallback, targets));
        },
        Expr::TryCatch { expr: inner, handler, .. } => {
            let inner = nikaia_std::boxed::open(inner);
            out.extend(tr_in_expr(inner, targets));
            out.extend(tr_in_block(handler, targets));
        },
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            out.extend(tr_in_expr(cond, targets));
            out.extend(tr_in_block(then_branch, targets));
            match else_branch {
                Some(other) => { out.extend(tr_in_block(other, targets)); },
                None => { },
            }
        },
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            out.extend(tr_in_expr(value, targets));
            for arm in arms.iter() {
                out.extend(tr_in_maybe((arm.guard).as_ref(), targets));
                out.extend(tr_in_expr(&arm.body, targets));
            }
        },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { out.extend(tr_in_maybe((field.value).as_ref(), targets)); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            out.extend(tr_in_expr(base, targets));
            for field in fields.iter() { out.extend(tr_in_maybe((field.value).as_ref(), targets)); }
        },
        Expr::Block(block, _) => { out.extend(tr_in_block(block, targets)); },
        Expr::Unsafe(block, _) => { out.extend(tr_in_block(block, targets)); },
        Expr::Overlap(block, _) => { out.extend(tr_in_block(block, targets)); },
        Expr::Closure { body, .. } => { out.extend(tr_in_block(body, targets)); },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); out.extend(tr_in_expr(body, targets)); },
        _ => { },
    }
    out
}

pub(crate) fn tr_reader(name: &str) -> bool { matches!(name, "len" | "is_empty" | "get" | "contains" | "contains_key" | "iter" | "clone" | "first" | "last" | "keys" | "values" | "text") }

pub(crate) fn tr_mark(words: &winnow_grammar::InternerContext, ruled: &collections::BTreeMap<String, collections::BTreeSet<String>>, field: winnow_grammar::Symbol, changed: &mut collections::BTreeSet<String>) {
    let text = words.resolve(field);
    for (name, fields) in ruled.iter() { if fields.contains(text) { changed.insert(name.to_owned()); } }
}

pub(crate) fn tr_mark_arg(words: &winnow_grammar::InternerContext, ruled: &collections::BTreeMap<String, collections::BTreeSet<String>>, in_impl: bool, arg: &Expr, changed: &mut collections::BTreeSet<String>) {
    match arg {
        Expr::Field { base, name, .. } => {
            let base = nikaia_std::boxed::open(base); let name = *name;
            if !(tr_is_self(base, words) && in_impl) { tr_mark(words, ruled, name, changed); }
        },
        _ => { },
    }
}

pub(crate) fn tr_mark_place(words: &winnow_grammar::InternerContext, ruled: &collections::BTreeMap<String, collections::BTreeSet<String>>, in_impl: bool, place: &Expr, changed: &mut collections::BTreeSet<String>) {
    match place {
        Expr::Field { base, name, .. } => {
            let base = nikaia_std::boxed::open(base); let name = *name;
            if !(tr_is_self(base, words) && in_impl) { tr_mark(words, ruled, name, changed); }
            tr_mark_place(words, ruled, in_impl, base, changed);
        },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); tr_mark_place(words, ruled, in_impl, base, changed); },
        _ => { },
    }
}

